export type ParsedClaimDistributionInstruction<
  TProgram extends string = typeof CACHAIN_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    owner: TAccountMetas[0];
    asset: TAccountMetas[1];
    position: TAccountMetas[2];
    contributionMint: TAccountMetas[3];
    ownerFunds: TAccountMetas[4];
    incomeVault: TAccountMetas[5];
    attestation: TAccountMetas[6];
    credential: TAccountMetas[7];
    contributionTokenProgram: TAccountMetas[8];
    eventAuthority: TAccountMetas[9];
    program: TAccountMetas[10];
  };
  data: ClaimDistributionInstructionData;
};

export function parseClaimDistributionInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedClaimDistributionInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 11,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      owner: getNextAccount(),
      asset: getNextAccount(),
      position: getNextAccount(),
      contributionMint: getNextAccount(),
      ownerFunds: getNextAccount(),
      incomeVault: getNextAccount(),
      attestation: getNextAccount(),
      credential: getNextAccount(),
      contributionTokenProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getClaimDistributionInstructionDataDecoder().decode(instruction.data),
  };
}
